@main
struct AteApp: App {
    let container: ModelContainer?
    @State private var store: AppStore

    init() {
        UNUserNotificationCenter.current().delegate = CookPlanNotificationRouter.shared
        SentryBootstrap.start()
        TabBarStyle.apply()
        #if DEBUG
        LiveDTProbe.installIfRequested()
        DogWaitPhaseDiagnostics.startIfRequested()
        MenuWaitCapture.startIfRequested()
        SearchFocusDiagnostic.startIfRequested()
        #endif
        if AppConfig.isUITesting {
            for k in ["ate.timerprefs.v1", "ate.cookSession.v1", CookCompletionOutbox.defaultsKey, CookReflectionOfferPolicy.defaultsKey, CookPlanStore.storageKey] { UserDefaults.standard.removeObject(forKey: k) }
            if !ProcessInfo.processInfo.arguments.contains("-qaPreserveSettings") {
                UserDefaults.standard.removeObject(forKey: "ate.settings.v1")
            }
        }
        // Corruption-safe open: a broken store is moved aside and a fresh one opened; never crashes (R-DATA-01).
        let corruptQA = AppConfig.isUITesting && ProcessInfo.processInfo.arguments.contains("-qaCorruptStore")
        let outcome: StoreRecovery.Outcome
        if corruptQA {
            let url = FileManager.default.temporaryDirectory.appendingPathComponent("qa-corrupt-\(UUID().uuidString).store")
            try? Data("not a sqlite database".utf8).write(to: url)
            outcome = StoreRecovery.open(url: url)
        } else {
            outcome = StoreRecovery.open(inMemory: AppConfig.isUITesting)
        }
        let c = outcome.container
        container = c
        #if DEBUG
        let upgradeRuntime = CanonicalUpgradeQARoute.prepareIfRequested()
        let st = AppStore(context: c?.mainContext,
                          nutritionDiaryRepository: InsightDestinationQAFixtures.repository(),
                          foodJournalRuntime: upgradeRuntime ?? CookJournalQARoute.runtime())
        if InsightDestinationQAFixtures.requested {
            precondition(st.foodJournalRuntime == nil, "Legacy Insights QA fixture cannot mix with canonical runtime")
            st.shopping = InsightDestinationQAFixtures.shopping()
        }
        DogfoodSavedRecipeQAFixtures.prepare(st)
        ExploreRetentionQAFixtures.prepare(st)
        if AppConfig.isUITesting && ProcessInfo.processInfo.arguments.contains("-qaJournalResetMemoryCredentials") {
            // These mock-auth Journal routes test reset/expiry, not OS Keychain entitlements.
            // Explicit per-process seam only: production credential validation is unchanged.
            var credentialBytes: Data?
            st.saveSessionCredentials = { data in
                credentialBytes = data
                return credentialBytes == data
            }
        }
        CookJournalQARoute.prepare(st)
        #else
        let st = AppStore(context: c?.mainContext)
        #endif
        if outcome.recovered || outcome.inMemoryFallback || (c == nil && !AppConfig.isUITesting) {
            st.recovery = RecoveryInfo(backupPath: outcome.backupURL?.lastPathComponent, inMemory: outcome.inMemoryFallback || c == nil, error: outcome.error)
        }
        StoreSaver.onFailure = { [weak st] msg in st?.show(msg, error: true, seconds: 4) }
        if AppConfig.isUITesting && ProcessInfo.processInfo.arguments.contains("-qaHealthRecipes") && st.recipes.isEmpty {
            st.recipes = HealthFixtures.library
        }
#if DEBUG
        // Hermetic canonical-nutrition route (#179 qualification): no-op unless flagged.
        CanonicalNutritionQARoute.prepareIfRequested(store: st)
#endif
        // #179 recipe-nutrition UI coverage: one recipe whose ingredient has no verified food match.
        if AppConfig.isUITesting && ProcessInfo.processInfo.arguments.contains("-qaNutritionFixtures") && st.recipes.isEmpty {
            var qaRecipe = RecipeCard()
            qaRecipe.id = "qa-nutrition-pap"
            qaRecipe.title = "QA pap and rice"
            qaRecipe.servings = 2
            qaRecipe.ingredients = [Ingredient(name: "pap", quantity: 200, unit: "g")]
            st.recipes = [qaRecipe]
        }
        _store = State(initialValue: st)
    }

    /// One typed expression keeps the shared modifiers attached across DEBUG compilation.
    private var rootContent: AnyView {
#if DEBUG
        CanonicalUpgradeQARoute.rootView() ?? CanonicalNutritionQARoute.rootView(store: store) ?? AnyView(RootView().modifier(CookJournalQAInspector()))
#else
        AnyView(RootView())
#endif
    }

    var body: some Scene {
        WindowGroup {
            rootContent
                .environment(store)
                .preferredColorScheme(store.settings.appearance.preferredColorScheme)
                .onOpenURL { store.handle(url: $0) }
                .task {
                    PhoneWatchBridge.shared.activate()
                    // ImageCreator can hang the simulator launch handshake on CI even though
                    // UI tests never exercise generated covers. Keep this capability probe on
                    // the production path; cover tests use explicit QA arguments and samples.
                    if !AppConfig.isUITesting { Task { await CoverStore.checkPlayground() } }
                    PhoneWatchBridge.shared.update(session: store.session)
                    if let u = AppConfig.launchURL { store.handle(url: u) }
                    if store.recovery != nil { await store.completeRecovery() }
                }
                .onContinueUserActivity(NSUserActivityTypeBrowsingWeb) { a in
                    if let u = a.webpageURL { store.handle(url: u) }
                }
        }
    }
}

/// Sticky timer summary bar, one per stack; it reserves layout space so bottom actions sit above it.
struct TimerBarInset: ViewModifier {
    @Environment(AppStore.self) private var store
    func body(content: Content) -> some View {
        // Applied once per NavigationStack (not per screen), so it can never show twice. Screen-level bottom
        // actions (Cook mode, Add recipe) use their own inner safeAreaInset and therefore sit directly above it.
        content.safeAreaInset(edge: .bottom, spacing: 0) {
            // iOS 26: at tab roots the timer lives in the tab bar's bottom accessory, so the inset only shows on pushed screens.
            if store.cookTarget == nil && !(TabChrome.usesAccessory && store.isAtTabRoot) {
                VStack(spacing: 0) {
                    if let session = store.cookSession { CookSessionMiniPlayer(session: session) }
                    if !store.timers.timers.isEmpty { TimerBar() }
                }
                .bottomChromeMeasured()
            }
        }
    }
}
extension View { func withTimerBar() -> some View { modifier(TimerBarInset()) } }

