        func inspect(_ layer: CALayer, depth: Int) {
            guard visited < 2048, depth < 64 else { return }
            visited += 1
            for key in layer.animationKeys() ?? [] {
                guard let animation = layer.animation(forKey: key) else { continue }
                observed += 1
                guard emitted < 64 else { continue }
